{
  "PROP-6a4369e9-pre-006": {
    "property_id": "PROP-6a4369e9-pre-006",
    "audit_result": {
      "property_id": "PROP-6a4369e9-pre-006",
      "classification": "vulnerability",
      "code_path": "beacon-chain/verification/data_column.go::SidecarDescendsFromFinalized::L337-354",
      "proof_trace": "Spec requires get_checkpoint_block(store, parent_root, finalized_epoch) == finalized_root to verify ancestry. Implementation only checks fc.HasNode(parentRoot) which verifies parent exists in fork choice store but does NOT verify it descends from finalized checkpoint. An attacker can send sidecars on finalized-conflicting forks that exist in fork choice.",
      "attack_scenario": "Attacker broadcasts data column sidecar with parent_root on a non-finalized fork (e.g., during reorg window). If parent exists in fork choice but conflicts with finalized checkpoint ancestry, gossip accepts it, causing honest nodes to propagate invalid sidecars and potentially reconstruct invalid blocks.",
      "checklist_id": "PROP-6a4369e9-pre-006"
    },
    "text": "Gossip validation must reject sidecar if finalized checkpoint is not an ancestor of block.",
    "assertion": "forall sidecar: accepted(sidecar) => is_ancestor(finalized_checkpoint.root, sidecar.block_root)",
    "covers": "SG-006",
    "severity": "CRITICAL",
    "type": "pre-condition"
  }
}

